  "test": "import pytest
from types import SimpleNamespace
from langfuse._client.span_processor import LangfuseSpanProcessor

# Helper to create a dummy span with given instrumentation_scope attributes
def make_dummy_span(attrs):
    scope = SimpleNamespace(attributes=attrs, name="dummy")
    span = SimpleNamespace(instrumentation_scope=scope)
    return span

@pytest.fixture
def processor():
    return LangfuseSpanProcessor(
        public_key="pk-test",
        secret_key="sk-test",
        base_url="http://localhost",
        span_exporter=type("Exporter", (), {"export": lambda self, spans: None, "shutdown": lambda self: None})(),
    )

def test_is_langfuse_project_span_uses_public_key(monkeypatch, processor):
    # Force is_langfuse_span to return True to focus on key lookup logic
    monkeypatch.setattr(
        "langfuse._client.span_processor.is_langfuse_span",
        lambda span: True,
    )
    span = make_dummy_span({"public_key": "pk-test"})
    assert processor._is_langfuse_project_span(span) is True

def test_is_langfuse_project_span_uses_fallback_key(monkeypatch, processor):
    monkeypatch.setattr(
        "langfuse._client.span_processor.is_langfuse_span",
        lambda span: True,
    )
    span = make_dummy_span({"x-langfuse-public-key": "pk-test"})
    assert processor._is_langfuse_project_span(span) is True

def test_is_langfuse_project_span_mismatch(monkeypatch, processor):
    monkeypatch.setattr(
        "langfuse._client.span_processor.is_langfuse_span",
        lambda span: True,
    )
    span = make_dummy_span({"public_key": "different"})
    assert processor._is_langfuse_project_span(span) is False
